use vstd::prelude::*;

verus! {

/// Returns the maximum element of a non‐empty vector.
/// 
/// Requires:
///   - lst.len() > 0
/// Ensures:
///   - for all j < lst.len(), lst[j] <= result
///   - there exists k < lst.len() with lst[k] == result
fn max_of_list(lst: &Vec<usize>) -> (result: usize)
    requires
        lst.len() > 0,
    ensures
        forall |j: usize| j < lst.len() ==> lst[j] <= result,
        exists |k: usize| k < lst.len() && lst[k] == result,
{
    let n = lst.len();
    // Initialize max_val to the first element; we know n > 0.
    let mut max_val = lst[0];
    // We will scan indices 1..n, maintaining:
    //   1 <= i <= n
    //   max_val = maximum of lst[0..i)
    //   there is some k < i with lst[k] == max_val
    let mut i: usize = 1;
    while i < n
        invariant
            1 <= i && i <= n,
            // all seen elements are ≤ max_val
            forall |j: usize| j < i ==> lst[j] <= max_val,
            // max_val is attained by some seen index
            exists |k: usize| k < i && lst[k] == max_val,
        decreases n - i,
    {
        let curr = lst[i];
        if curr > max_val {
            max_val = curr;
        }
        i = i + 1;
    }
    // At this point i == n, so max_val is the maximum over lst[0..n) == whole vector.
    result = max_val;
}

} // verus! 

